-- Migration 051: SEO description drafts, batch 2 — the next 50 non-wallpaper
-- categories by active-product count (продовження 049 від 2026-09-14;
-- відбір 2026-09-15: categories без опису, топ-50 за кількістю активних
-- товарів, слаги shpaleri-* та 20 слагів із 049 виключені).
--
-- Format mirrors 049 byte-for-byte in style: plain factual Ukrainian prose,
-- 3 paragraphs, no marketing claims, no invented brand/warranty facts;
-- apostrophes written as ’ so no SQL-quote escaping is needed. The same
-- texts are appended to data/category-seo-texts.sql as UPDATEs —
-- tests/category-seo-faq.test.ts pins the seed/migration consistency and
-- scans both migrations for banned marketing wording.
--
-- Idempotent: INSERT ... SELECT ... JOIN ... ON CONFLICT (slug) DO UPDATE.
-- INSERT ... SELECT ... JOIN, не голый VALUES: Postgres проверяет NOT NULL
-- новой строки ДО разрешения конфликта, поэтому опущенный NOT NULL `name`
-- уронил бы весь statement с 23502, хотя каждый slug здесь конфликтует
-- (категории существуют). Джойн подставляет name существующей категории и
-- молча пропускает slug, которого вдруг не оказалось в БД. ВЛАДЕЛЕЦЬ ПРАВИТЬ
-- ТЕКСТИ В АДМІНЦІ — після ручних правок НЕ перезастосовувати цю міграцію.
--
-- VERIFY-PRE:
--   select count(*) from categories
--    where is_active and coalesce(description,'')='' and slug not like 'shpaleri%';
--   -- >0 (top-50 by active-product count all had no description)
-- VERIFY-POST:
--   select count(*) from categories
--    where coalesce(description,'')<>'' and slug not like 'shpaleri%';
--   -- 70 (20 из 049 + 50 из этой миграции)

begin;

insert into categories (slug, name, description)
select v.slug, c.name, v.description
from (values
('kavovarky-1408', 'Кавоварки для дому та офісу: крапельні моделі, що готують напій у кувшині на кілька порцій, ріжкові для кави в чалдах і компактні апарати для еспресо. Об’єм резервуара для води визначає, скільки чашок виходить за один цикл, — від двох-трьох до повного кувшина на компанію.

Обирайте тип під звичний напій: крапельна зручна для чорної кави великими порціями, ріжкова дає густіший смак, а для молочних напоїв знадобиться капучинатор. Звертайте увагу на підігрів кувшина, багаторазовий фільтр і простоту зняття деталей для миття.

Накип головний ворог смаку: періодично очищуйте прилад лимонною кислотою або спеціальним засобом. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('kelykhy-fuzhery-kukholi-1371', 'Питне скло на кожен день і для святкового столу: келихи для вина й шампанського, фужери, пивні кухлі та чарки. Скло буває звичайним і тонким, з видовженою чашею та вузьким обідком, який не заважає відчувати смак напою.

Форму підбирають під напій: широка чаша розкриває аромат червоного вина, вузька й висока тримає бульбашки шампанського, важке дно з товстими стінками характерне для пивних кухлів. Зважайте на об’єм і на маркування — чи можна мити келихи в посудомийній машині.

Тонке скло мийте руками без абразивних засобів і берегіть від різких перепадів температур, щоб не допустити тріщин. Доставка — по всій Україні, у Кривому Розі доступний самовивіз.'),
('svch-pechi-85', 'СВЧ-печі для розігріву їжі, розморожування продуктів і швидкого готування: соло моделі на стільницю різного об’єму, з механічним поворотним або сенсорним керуванням. Типовий об’єм — від компактних пічок для однієї-двох порцій до великих на родину.

Об’єм підбирайте за кількістю людей і розміром посуду, який плануєте ставити всередину. З корисних функцій зважайте на потужність і кількість її рівнів, режими розморожування за вагою чи часом, автоматичні програми для типових страв та наявність гриля для скоринки.

Використовуйте посуд без металевого декору й протирайте камеру вологою серветкою вчасно — засохлі бризки гріються й пахнуть під час роботи. Замовлення доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('elektrobrytvy-1424', 'Електробритви двох типів: сіткові з плоскою голівкою, що дає близьке й швидке гоління, та роторні з круглими голівками, які краще проходять контури обличчя. Моделі розрізняються за режимами — сухе гоління або вологе з піною під душем.

Для чутливої шкіри зважайте на сіткові моделі та наявність режимів для делікатного гоління, для жорсткішої щетини — роторні. Практичні деталі: час автономної роботи, індикація заряду, швидке заряджання, можливість промивати голівку під водою.

Голівки зношуються в міру використання й потребують заміни — перевірте їхню доступність для вашої моделі. Регулярне очищення тримає тягу та якість гоління. Доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('multypechi-1642', 'Мультипечі, або аерогрилі, — компактні конвекційні печі: нагрівач і вентилятор ганяють гаряче повітря навколо продуктів у скляній колбі або закритій чаші. У такій печі печуть м’ясо та овочі, смажать картоплю, гріють готові страви й навіть роблять заготовки.

Обирайте за об’ємом колби чи чаші — від невеликих на пару порцій до моделей на цілу курку. Практичні параметри: діапазон температур, кількість режимів і таймер, решітка та щипці в комплекті, зручність миття кришки з елементами керування.

Скляну колбу ставте на термостійку поверхню й берегіть від ударів; мийте після остигання, без різких перепадів температури. Доставка по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('dukhovi-shafy-202', 'Вбудовані духові шафи для установки в кухонний гарнітур: електричні та газові, з конвекцією для рівномірного пропікання на кількох рівнях, грилем і наборами режимів від простого нагріву до програм для м’яса й випічки.

Ширину звіряйте з нішею — поширений стандарт 60 см, зустрічаються й компактні чи широкі моделі. Зважайте на спосіб очищення (каталітична емаль, парове або піроліз), кількість рівнів і телескопічні направляючі, клас енергоефективності та тип керування.

Заміри ніші й розетки плануйте заздалегідь, а після встановлення прогрійте шафу порожньою за інструкцією, щоб прибрати запах новизни. Доставка по всій Україні, у Кривому Розі доступний самовивіз.'),
('vyrivniuvachi-dlia-volossia-1431', 'Праски для вирівнювання волосся: робочі пластини бувають металевими, керамічними й турмаліновими, а за шириною — вузькими для локонів і короткого волосся та широкими для довгого.

Ключовий параметр — регулювання температури: тонкому та фарбованому волоссю вистачає нижчих значень, густому й жорсткому потрібні вищі. Плаваючі пластини рівномірно притискають пасмо, функція іонізації зменшує електризацію, швидкий нагрів економить час зранку.

Перед укладанням наносьте термозахист і не тримайте праску на одній ділянці довго: це найпростіший спосіб зберегти волосся здоровим. Доставка по всій Україні, у Кривому Розі працює самовивіз.'),
('vodonahrivachi-498', 'Водонагрівачі для дому: накопичувальні бойлери з баком на 30–100 літрів, які гріють і тримають запас гарячої води, та проточні, що нагрівають потік одразу. Форма буває круглою й пласкою — під просторий санвузол чи впритул до стіни.

Об’єм підбирайте за кількістю людей: для однієї особи зазвичай вистачає 30–50 літрів, для родини з кількох — 80 і більше. Зважайте на потужність ТЕНа, внутрішнє покриття баку (емаль або нержавіюча сталь), магнієвий анод, терморегулятор і захист від увімкнення без води.

Бойлер потребує заземленої розетки й періодичної чистки від накипу із заміною анода — так бак служить помітно довше. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('tostery-1417', 'Тостери для швидкого сніданку: моделі на два й чотири слоти, з віконцем для спостереження за скибками та регулятором ступеня підсмажування — від ледь теплого до хрусткої скоринки.

Звертайте увагу на ширину слотів, якщо любите хліб товстими скибками, і на додаткові режими: розморожування, підігрів без підсмажування, скасування. Зручні підйом скибок вище краю, щоб не обпектися, і знімний піддон для крихт, який легко витряхнути.

Тостер простий у догляді: регулярно спорожняйте піддон і не діставайте скибки металевими предметами — тільки дерев’яними або силіконовими. Доставка по всій Україні, у Кривому Розі працює самовивіз.'),
('kombainy-1401', 'Кухонні комбайни з одним моторним блоком і наборами насадок: подрібнюють овочі та м’ясо, шаткують салати, труть на терки, міслять тісто й збивають креми. Від потужності та об’єму чаші залежить, які об’єми продуктів приладу під силу.

Обирайте комплект насадок під свої звички: диски для шатківки, терки різного розміру, ножі для подрібнення, віночок і гак для тіста. Практичні деталі — кілька швидкостей та імпульсний режим, матеріал чаші, можливість мити насадки в посудомийній машині.

Розбирайте й мийте деталі одразу після роботи: застиглі залишки тіста відмиваються помітно важче. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('kombinovani-1539', 'Комбіновані плити поєднують газові конфорки зверху та електричну духову шафу знизу: газ дає швидкий нагрів і контроль полум’я, електрична духовка — стабільну температуру для випічки.

Типові ширини — 50 і 60 см; звіряйте габарити з місцем на кухні. З практичних функцій зважайте на електрозапалювання конфорок і духовки, газконтроль, який перекриває подачу газу, якщо полум’я згасло, наявність гриля та конвекції в шафі, матеріал панелі й ґрат.

Підключення до газової мережі виконуйте тільки фахівці: самостійні з’єднання небезпечні, а після монтажу перевіряють герметичність. Доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('sklianky-1375', 'Склянки для води, соків, чаю та коктейлів: звичайне й загартоване скло, моделі з подвійними стінками, які тримають температуру напою, з декором і без. Об’єми різняться від маленьких стопок до великих хайболів.

Об’єм підбирають під напій: маленькі під міцне, середні під соки й компоти, великі під коктейлі з льодом. Зважайте на товщину стінок і стійкість до подряпин, а маркування підкаже, чи можна склянку мити в посудомийній машині.

Загартоване скло витримує гарячий напій і дрібні побутові удари, але будь-яке скло не любить різких перепадів температур — не наливайте окріп у холодну склянку. Доставка — по всій Україні, у Кривому Розі доступний самовивіз.'),
('miksery-1403', 'Міксери для збивання тіста, кремів і білків двох форматів: ручні, якими працюєте прямо в мисці, та стаціонарні з чашею й підставкою, які звільняють руки. У комплекті зазвичай два віночки, а в частинах моделей — гачки для тіста.

Зважайте на кількість швидкостей: низька потрібна, щоб не розплескати борошно, висока — для пишних білків. Для стаціонарних моделей важливі об’єм чаші та наявність планетарного руху насадок, який опрацьовує суміш рівномірно.

Віночки мийте одразу після збивання — застиглий крем і білки відходять важче, ніж свіжі залишки. Замовлення доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('hryl-1412', 'Електрогрилі для домашнього приготування м’яса, риби, овочів і сендвічів: контактні моделі з верхньою панеллю-пресом та відкриті з ребристою поверхнею, на якій залишаються характерні смужки.

Обирайте за площею робочої поверхні — скільки порцій готуєте за раз, — і за потужністю, від якої залежить швидкість прожарювання. Практичні деталі: регулювання температури, знімні панелі, які можна мити, і піддон для стікання жиру.

Гриль працює з димком, тож кухню варто провітрювати; поверхню чистіть після остигання м’якою губкою, без абразивів, щоб не подряпати покриття. Доставка по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('feny-shchitky-1429', 'Фени-щітки поєднують сушіння та укладання: кругла насадка зі щетиною обертається й одночасно висушує пасмо, надаючи об’єму або закручуючи кінці. Формати — від компактних моделей до наборів із кількома насадками різного діаметру.

Діаметр насадки підбирайте під довжину волосся: короткому підходять малі, довгому — ширші. Зважайте на кількість режимів температури й обертів, функцію іонізації проти електризації та можливість працювати з холодним повітрям для фіксації укладки.

Не тримайте насадку на одній ділянці довго й періодично очищуйте щетину від волосся: прилад працюватиме рівніше й прослужить довше. Доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('inshe-1418', 'Розділ збирає дрібну кухонну техніку, яка не ввійшла в окремі підкатегорії: вакууматори для пакування продуктів, льодогенератори, морожениці для домашнього морозива та інші прилади для окремих кухонних завдань.

Оскільки категорія різноманітна, орієнтуйтеся на конкретну задачу: для вакууматора зважайте на тип і доступність пакетів, для льодогенератора — на продуктивність і об’єм бункера, для морожениці — на об’єм чаші та час приготування.

Перед замовленням перевіряйте в описі товару набір функцій і комплектність; якщо потрібна деталь — менеджер уточнить характеристики. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('hazovi-1535', 'Газові плити з духовою шафою: чотири конфорки різної потужності, електрозапалювання, газконтроль, який перекриває подачу газу при згасанні полум’я. Панель буває з емалі, нержавіючої сталі або склокераміки — від матеріалу залежить догляд.

Звіряйте ширину (поширені 50 і 60 см) і тип духовки: проста газова, з грилем або з газовою конвекцією. Практичні деталі — знімні ґрати й ручки, які легко мити, розташування ящика для посуду, підсвітка духовки.

Підключення до газової мережі довіряйте фахівцям і не забувайте про вентиляцію: полум’я споживає повітря, тож витяг у кухні має працювати справно. Доставка по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('aksesuary-do-klimatychnoi-tekhniky-1332', 'Витратні матеріали до кліматичної техніки: змінні фільтри для очищувачів повітря (HEPA, вуглецеві, комбіновані), фільтри-зволожувачі, пульти та інші комплектуючі. Саме фільтр робить основну роботу з очищення повітря, тому його стан визначає результат.

Фільтр підбирається за моделлю приладу: звіряйте маркування на корпусі та список сумісних моделей в описі товару. Оригінальні та сумісні варіанти різняться за строком служби — зважайте на це при виборі.

Міняйте фільтри за індикацією або графіком з інструкції: забитий фільтр знижує ефективність очищення, підвищує шум і навантаження на мотор. Доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('morozylni-kamery-ta-lari-217', 'Морозильна техніка двох форматів: вертикальні камері-шафи з ящиками, які зручно стоять на компактній площі, та горизонтальні ларі з відкидною кришкою для великих запасів м’яса, риби й заготовок.

Об’єм підбирайте за обсягом запасів: для родини зазвичай вистачає 100–200 літрів, ларі беруть і більші. Зважайте на кількість ящиків і полиць, режим швидкого заморожування, індикацію температури, напрямок перевішування дверей чи наявність замка у ларі.

Залишайте вентиляційні зазори по інструкції та не ставте техніку біля плит і радіаторів: перегрів збільшує витрату електроенергії. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('buterbrodnytsi-ta-vafelnytsi-1411', 'Бутербродниці та вафельниці з нагрівальними панелями: рифлені панелі залишають фігурні краї на сендвічах і візерунок на вафлях, пласкі підходять для паніні. Покриття панелей антипригарне, тож тісто й начинку не треба змащувати маслом.

Обирайте форму панелей під страви: трикутні відділення для сендвічів, квадратні для віденських вафель, круглі для тонких. Практичні деталі — кількість порцій за раз, індикатор нагріву, замок кришки та можливість ставити прилад вертикально на зберігання.

Антипригарне покриття чистіть м’якою губкою після остигання; абразиви та металеві предмети його псують. Доставка — по всій Україні, у Кривому Розі доступний самовивіз.'),
('pylosmoky-z-konteinerom-99', 'Пилосмоки з циклонним контейнером: пил і сміття збираються у прозорий резервуар без одноразових мішків, який після прибирання спорожняють і промивають. Формати — від компактних вертикальних до повнорозмірних.

Обирайте за силу всмоктування, об’єм контейнера та тип фільтрації: фільтри тонкого очищення затримують дрібний пил і важливі для дому з дітьми чи алергіками. Для килимів потрібна турбощітка, для гладких підлог вистачить стандартної насадки.

Тяга залежить від чистоти фільтрів і ступеня заповнення контейнера, тож очищуйте їх регулярно — це простіша причина слабкого всмоктування. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('shchyptsi-dlia-zavyvky-1430', 'Щипці для завивки з нагрівальною частиною у вигляді циліндра або конуса: діаметри різняться від вузьких для дрібних локонів до широких для великих м’яких хвиль. Покриття — керамічне або турмалінове, яке рівномірніше розподіляє тепло.

Діаметр підбирайте під довжину волосся й бажаний результат: короткому волоссю вистачає вузьких стержнів, для довгого зручніші ширші. Зважайте на регулювання температури, наявність затискача або конусну форму без нього, довжину та обертання шнура.

Для фарбованого й пошкодженого волосся обирайте нижчі температури та наносьте термозахист перед укладанням. Доставка по всій Україні, у Кривому Розі працює самовивіз.'),
('sklokeramichni-1537', 'Електричні плити зі склокерамічною поверхнею: конфорки швидкого нагріву або індукційні, які гріють сам посуд, залишаючи панель прохолоднішою. Гладка поверхня проста в догляді й виглядає охайно.

Для індукційних конфорок потрібен посуд із феромагнітним дном — перевірте маркування на дні каструль. Зважайте на кількість і розмір конфорок, розширені зони для великого посуду, індикатори залишкового тепла та тип керування — поворотне або сенсорне.

Склокераміку протирайте м’якою губкою без абразивних засобів; пластир із цукру чи пластику зчищайте спеціальним скребком, поки поверхня ще тепла. Доставка по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('stolovi-servizy-1388', 'Столові сервізи на родину та гостей: мілкі й глибокі тарілки, салатники, іноді додані оселедцеві тарілки, соусники або чайні пари. Матеріали — фарфор, кераміка, фаянс: від них залежать вага, прозорість і стійкість до подряпин.

Головне при виборі — склад: скільки персон і які предмети на кожну, чи вистачає глибоких тарілок для перших страв. Перевіряйте маркування на сумісність із мікрохвильовою піччю та посудомийною машиною, якщо плануєте ними користуватися щодня.

Повний сервіз зручно доповнювати поштучно тарілками того ж дизайну, якщо щось розіб’ється. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('multyvarky-1406', 'Мультиварки для готування в одній чаші: каші, супи, тушкування, плов, випічка, йогурт — програми задають температуру й час, а відкладений старт готує сніданок до пробудження. Чаша з антипригарним покриттям миється просто.

Об’єм чаші підбирайте за розміром родини: 3–4 літри вистачає для двох-трьох осіб, 5 літрів і більше — для великої. Зважайте на потужність, кількість програм і можливість ручного налаштування температури та часу; окремий клас — мультиварки-скороварки під тиском.

Мішайте страви силіконовими або дерев’яними лопатками, щоб не подряпати покриття чаші, а гумову прокладку кришки промивайте регулярно. Доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('sushylni-mashyny-1123', 'Сушильні машини завершують прання без розвісок: конденсаційні моделі збирають вологу в контейнер, техніка з тепловим насосом працює при нижчих температурах і витрачає менше електроенергії.

Завантаження підбирайте під пральну машину — зазвичай 7–9 кг білизни. Практичні параметри: програми для делікатних тканин і вовни, режим освіження, фільтр для ворсу, індикація заповнення контейнера, можливість установки в колону з пральною машиною.

Фільтр для ворсу чистіть після кожного циклу, конденсатор і контейнер — за графіком з інструкції: від цього залежить час сушки й витрата електроенергії. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('dlia-sokiv-142', 'Соковижималки двох типів: центробіжні з швидким обертанням, які впораються з твердими яблуками та морквою, і шнекові холодного віджиму, що працюють повільніше, але краще беруться за м’які фрукти й листову зелень. Окремо є цитрусові преси для апельсинів і грейпфрутів.

Тип підбирайте під продукти, які вижимаєте найчастіше. Зважайте на потужність мотора, ширину завантажувальної горловини — чи влізе ціле яблуко, об’єм резервуара для соку й відсік для м’якоті, простоту розбирання для миття.

Соковижималку розбирайте й промивайте одразу після роботи: м’якоть засихає швидко, і миття перетворюється на роботу. Доставка — по всій Україні, у Кривому Розі доступний самовивіз.'),
('kholodylnyky-1216', 'Вбудовані холодильники, які закриваються кухонним фасадом і не порушують лінію гарнітура: однокамерні та двокамерні, з морозильною камерою або без неї, для установки в нішу над чи під робочою поверхнею.

Перед замовленням звіряйте габарити ніші — висоту, ширину, глибину — з інструкцією конкретної моделі. Зважайте на корисний об’єм, систему розморожування, клас енергоефективності та можливість перевісити двері під свій план кухні.

Вбудованій техніці потрібні вентиляційні зазори, вказані в інструкції: без них компресор перегрівається і працює на знос. Доставка по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('doshka-dlia-narizannia-1346', 'Обробні дошки для нарізання, подачі й сервірування: дерево та бамбук, пластик, скло з принтом; розміри від маленьких дощечок для сніданку до великих для тіста й м’яса.

Матеріал підбирають під задачу: пластикову дошку зручно мити гарячою водою після м’яса та риби, дерев’яна і бамбукова м’якше для лез і годиться для хліба та подачі, скляна не вбирає запахи, але тупить ножі. Практичні деталі — жолоб для соку, ніжки та отвір для підвісу.

Тримайте окремі дошки для сирого м’яса та готових продуктів; дерев’яні не мийте в посудомийній машині й періодично змащуйте харчовою олією. Доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('svch-pechi-1217', 'Вбудовані СВЧ-печі, які встановлюються в кухонну шафу, нерідко на рівні очей: звільняють стільницю й органічно входять у гарнітур разом із духовою шафою того ж дизайну.

Об’єм підбирайте за розміром посуду, який ставите всередину. Зважайте на потужність і кількість її рівнів, режими розморожування, автоматичні програми, а в комбінованих моделях — на гриль і конвекцію. Рамка для вбудування зазвичай входить у комплект або докупляється.

Заздалегідь звірте розміри ніші та розташування розетки; посуд використовуйте без металевого декору, а камеру протирайте вчасно від бризок. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('aksesuary-do-tekhniky-dlia-domu-1336', 'Витратні матеріали та приладдя для техніки догляду за домом: мішки для пилососів, фільтри — моторні, вихідні, HEPA, насадки та щітки, засоби для миття вікон і підлоги в скло- і швабрах-пилососах.

Аксесуар підбирають за моделлю приладу: у кожному описі є список сумісних пристроїв, звіряйте маркування свого пилососа чи швабри. Тип мішка впливає на фільтрацію: синтетичні затримують дрібний пил краще за паперові.

Тримайте запас мішків і фільтрів удома: заміна вчасно підтримує тягу пилососа і чистоту повітря на виході. Зношену щітку теж міняйте — вона гірше збирає сміття з килима. Доставка по всій Україні, у Кривому Розі працює самовивіз.'),
('kryshky-1365', 'Кришки до каструль, сковорідок, сотейників і форм: скляні з отвором для пари, металеві, пластикові для контейнерів, а також універсальні моделі, що підходять на кілька діаметрів завдяки силіконовому обідку.

Діаметр підбирають під край посуду; ручка буває з термостійкого бакеліту, металу або силіону — від матеріалу залежить, чи можна брати кришку без прихватки. Скляна кришка з паровідводом дозволяє стежити за стравою, не піднімаючи її.

Перевіряйте маркування щодо духовки: не всі скляні та металеві кришки призначені для нагріву в шафі. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('vahy-kukhonni-1420', 'Кухонні ваги для рецептів, дієтичного харчування та порцій: електронні моделі з платформою зі скла або пластику, межа зважування зазвичай 5–10 кг, крок — 1 грам.

Зважайте на потрібні одиниці вимірювання — грами, унції, мілілітри для рідин, — на функцію тарування ваги миски та на живлення: батарейки або акумулятор. Для тіста й кондитерських справ важлива точність на малих вагах.

Ставте посуд у центрі платформи й протирайте її вологою серветкою, не занурюючи прилад у воду. У частини моделей додатково є таймер і функція годинника, що зручно на кухні. Доставка — по всій Україні, у Кривому Розі доступний самовивіз.'),
('kondytsionery-180', 'Кондиціонери для дому та офісу: спліт-системи із зовнішнім і внутрішнім блоком та мобільні моделі на коліщатках, які виводять тепле повітря через вікно. Базові режими — охолодження, осушення, вентиляція; багато моделей гріють у міжсезоння.

Потужність підбирають під площу приміщення: недостатня буде працювати без результату в спеку, надмірна коштує дорожче й часто вмикається. Для спалень зважайте на рівень шуму внутрішнього блоку, для економії — на інверторне керування.

Монтаж спліт-системи виконують спеціалісти з вакуумуванням траси, а фільтри внутрішнього блоку варто промивати кілька разів за сезон. Доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('kavomolky-1462', 'Кавомолки двох типів: ножові, що подрібнюють зерно обертовими лезами, та жорнові, які мелють зерно між двома дисками й дають рівномірну фракцію — це важливо для еспресо та альтернативних способів заварювання.

Регулювання помелу — головний параметр: від пилу для турки до крупного для френч-преса. У ножових моделях зважайте на об’єм камери та імпульсний режим, у жорнових — на матеріал жорнів і кількість ступенів помелу.

Видаляйте залишки кави щіточкою після кожного помелу: старе мелення з оліями гірчить і псує смак наступної порції. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('dlia-posudomyinykh-ta-pralnykh-mashyn-1471', 'Приладдя та засоби догляду для посудомийних і пральних машин: з’єднувальні й наливні шланги, панелі-накладки на фасад, засоби для чищення машин від накипу та забруднень, приладдя для завантаження.

Шланги та комплектуючі підбирають за моделлю машини — звіряйте розміри, тип різьблення та список сумісності в описі. Засоби для чищення бувають для посудомийних і для пральних машин, тож не плутайте призначення.

Періодичне чищення машини спеціальним засобом прибирає накип і запахи, а огляд шлангів і ущільнювачів дверцят допомагає помітити тріщину до протікання. Доставка по всій Україні, у Кривому Розі працює самовивіз.'),
('vahy-106', 'Підлогові ваги для контролю ваги: механічні зі стрілкою та електронні з дисплеєм, зі скляною або пластиковою платформою різного дизайну — від квадратних до заокруглених моделей.

Межа зважування зазвичай 150–180 кг, крок шкали — 100 грамів. В аналізаторах складу тіла додатково відображаються індекс маси тіла та відсоток води й жиру: ці показники орієнтовні, але зручні для спостереження за динамікою.

Ставте ваги на рівну тверду підлогу — на килимі показники зміщуються, і зважуйтеся в однакових умовах, щоб порівнювати результати. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('zapchastyny-ta-komplektuiuchi-1515', 'Комплектуючі для ремонту великої побутової техніки: компресори для холодильників, пускові реле та інші вузли, які дозволяють відновити роботу приладу без заміни його цілком.

Запчастину підбирають за моделлю техніки: звіряйте маркування на корпусі старого вузла й характеристики в описі — для компресорів це холодопродуктивність і тип холодоагенту. Якщо сумніваєтеся, менеджер допоможе звірити деталь перед замовленням.

Встановлення компресора потребує майстра з обладнанням для роботи з холодильним контуром: це не робота для самостійного ремонту. Доставка по всій Україні, у Кривому Розі працює самовивіз.'),
('posudomyini-mashyny-205', 'Вбудовані посудомийні машини: повністю вбудовані моделі з панеллю керування на торці дверцят і частково вбудовані з відкритою панеллю. Поширені ширини — 45 і 60 см, місткість від вузьких на 9 комплектів до повнорозмірних на 14–15.

Ширину підбирають під нішу, місткість — під кількість посуду в родині. Зважайте на класи миття та сушки, рівень шуму для відкритих кухонь, третій рівень завантаження для приладів і програму половинного завантаження, коли посуду небагато.

Сіль і ополіскувач засипають за жорсткістю води, а перед замовленням звіряють підведення води, зливу та розетку біля місця установки. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('mysky-1350', 'Миски для замісу тіста, салатів, маринадів і зберігання: скло, кераміка, пластик, нержавіюча сталь. Розміри — від маленьких піал для соусів до великих мисок на кілька літрів для тіста.

Матеріал підбирають під задачу: скляну миску можна гріти в мікрохвильовій печі, стальна легка й не б’ється, пластик зручний для холодильника, особливо з кришками. Звертайте увагу на стійкість до подряпин і на маркування щодо нагріву.

Скло та кераміку берегіть від різких перепадів температур — від окропу в холодний посуд з’являються тріщини. Миска з кришкою перетворюється на контейнер для холодильника. Доставляємо по всій Україні, у Кривому Розі доступний самовивіз.'),
('posudomyini-mashyny-94', 'Окремостоячі посудомийні машини, які ставлять поруч із кухонними шафами або під стільницю: повнорозмірні на 12–15 комплектів, вузькі на 9 і компактні настільні моделі на 4–6 комплектів для невеликих кухонь.

Обирайте за місткістю та набором програм: інтенсивна для каструль, еко для економії, швидка для злегка забрудненого посуду. Практичні параметри — тип сушки, захист від протікань, індикація солі й ополіскувача, рівень шуму.

Для установки під стільницею звірте висоту з регулюванням ніжок, а модель для відкритої установки — з дизайном фасаду. Доставка по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('aksesuary-do-kukhonnoi-tekhniky-1335', 'Змінні аксесуари до кухонної техніки: фільтри та щітки для роботів-пилососів, насадки до кухонних процесорів і міксерів, рулони та касети для вакууматорів, фільтри для витяжок і чайників.

Аксесуар підбирають за моделлю приладу: у кожному описі перелічено сумісні пристрої, звіряйте артикул або маркування свого. Витратні матеріали від різних виробників взаємозамінні рідко, тож краще брати сумісні, а не близькі на вигляд.

Зношені щітки та забиті фільтри помітно знижують результат роботи приладу, тож тримайте комплект на заміну заздалегідь. Замовлення доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('nastilni-plyty-1414', 'Настільні плити для дачі, орендованого житла та кухонь без стаціонарної плити: газові моделі, що працюють від балона, електричні з дисковими конфорками та індукційні, яким потрібен посуд із феромагнітним дном.

Обирайте за типом живлення — газ або розетка, — за кількістю конфорок і матеріалом панелі. У газових моделях зважайте на автоматичне запалювання та газконтроль, в електричних — на регулювання температури й стійкість корпусу до нагріву.

Газові плити використовуйте в провітрюваних приміщеннях і перевіряйте щільність з’єднань із балоном; після роботи перекривайте подачу газу. Доставка — по всій Україні, у Кривому Розі доступний самовивіз.'),
('miasorubky-1404', 'М’ясорубки для домашнього фаршу, котлет і заготовок: електричні моделі з набором ґраток різного діаметра отворів, насадкою-кеббе для начинок, а в частинах комплектах — шінківкою для овочів.

Продуктивність указують у кілограмах за хвилину; зважайте також на потужність, реверс, який виштовхує жили, і матеріал шнека з ножем. Металеві деталі довговічніші за пластикові, а знімні частини мають легко розбиратися для миття.

Розбирайте й мийте деталі одразу після роботи — фарш засихає швидко; ґратки та ніж витирають насухо, щоб не з’явилася іржа. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('epiliatory-1423', 'Епілятори для видалення волосся з коренем: робоча голівка з пінцетами або дисками вискубує волоски, а кількість пінцетів визначає швидкість процедури — від компактних 20 до 40 і більше.

Зважайте на кількість швидкостей: низька зручніша для чутливих зон, висока — для ніг. Комфортніші моделі, які можна використовувати з водою, мають насадки для пахв і зони бікіні, підсвітку для коротких волосків і масажні насадки.

Процедура переноситься легше після теплої ванни, а з часом шкіра звикає; після епіляції зручний заспокійливий крем без спирту. Доставка по всій Україні, у Кривому Розі працює самовивіз.'),
('hlechyky-1373', 'Глечики для води, соків, компотів і лимонадів: скло, пластик і кераміка; об’єми зазвичай 1–2 літри, з кришкою, носиком та ручкою, у частинах моделях — із ситечком для м’якоті чи листя чаю.

Об’єм підбирайте під родину, матеріал — під звички: скло показує вміст і не вбирає запахи, пластик легкий і безпечний для дитячого столу. Перевірте, чи щільно сидить кришка та чи ллє носик без крапель — це щоденні дрібниці.

Перш ніж наливати гарячий напій, перевірте маркування: не всі пластикові глечики розраховані на окріп. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати замовлення самовивозом.'),
('barbekiu-1358', 'Набори для барбекю та гриля: стейкові ножі, вилки, мусати й кухлі в чохлах або валізах, які зручно возити на дачу. Леза з нержавіючої сталі, рукоятки з дерева або композиту, частина наборів доповнена обробними дошками для подачі.

Склад наборів різниться від трьох предметів до повних комплектів на компанію, тож звіряйте список: краще менший набір предметів, якими ви справді користуєтеся. Звертайте увагу на товщину лез, зручність рукояток і жорсткість чохла.

Мийте приладдя вручну та витірайте насухо, не залишайте сталеві леза у вологому чохлі, а перед використанням правте мусатом. Доставка по всій Україні, у Кривому Розі доступний самовивіз.'),
('komplekty-1646', 'Комплекти вбудованої техніки: духова шафа та варильна поверхня в єдиному дизайні, які продаються разом. Такий набір позбавляє підбору кольорів і стилю керування окремо — фасади та ручки збігаються від заводу.

Звіряйте склад комплекту: тип варильної поверхні (газова, електрична, індукційна), тип і набір режимів духової шафи, чи входять у комплект ґрати, противні та рамки. Розміри обох приладів мають підходити до ніш вашого гарнітура.

Перед замовленням порівняйте ціну комплекту з окремими приладами того ж рівня — іноді збірка окремо коштує так само. Доставляємо по всій Україні, у Кривому Розі працює самовивіз.'),
('pylosmoky-z-mishkom-98', 'Пилосмоки з мішком для пилу: сміття збирається в мішок, який знімають і викидають ціликом — при спорожненні менше контакту з пилом, ніж із контейнером. Формати — від компактних до повнорозмірних моделей.

Зважайте на силу всмоктування, об’єм мішка та індикатор його заповнення. Тип мішка теж має значення: синтетичні затримують дрібніший пил за паперові; перевірте, чи легко знайти заміну саме для вашої моделі — це визначає витрати на все життя пилососа.

Переповнений мішок різко знижує тягу, тож змінюйте його вчасно й не забувайте про фільтри тонкого очищення. Замовлення доставляємо по всій Україні, у Кривому Розі можна забрати товар самовивозом.'),
('prynalezhnosti-dlia-nozhiv-1362', 'Приладдя для кухонних ножів: мусати для правки леза, точилки — від простих двоступеневих до моделей з алмазним напиленням, підставки та магнітні тримачі для зберігання.

Точилку підбирають під тип ножів: для керамічних лез потрібні окремі моделі, для звичайної сталі підходить більшість. Мусат вибирають за довжиною леза — він має бути не коротшим, а точильний кут звіряйте з ножами, які ви правите.

Правте лезо регулярно: тупий ніж зісковзує з продукту й небезпечніший гострого, а зберігання в підставці або на магнітній планці тримає заточку довше. Замовлення доставляємо по всій Україні, у Кривому Розі доступний самовивіз.')
) as v(slug, description)
join categories c on c.slug = v.slug
on conflict (slug) do update set description = excluded.description;

commit;
